"use client";
// @zeus-internal
import { useId as useArtemisInstanceId } from "react";
import { motion, useInView, useReducedMotion } from "motion/react";
import { useEffect, useRef, useState, type ReactNode } from "react";
import { ARTEMIS_EASE_OUT } from "../../../lib/ease";
import { NumberTicker } from "./01-segmented-progress/number-ticker";
const SEGMENTS = 40;
const SEGMENT_DURATION = 0.22;
const SEGMENT_STAGGER = 0.024;
const VALUE_DURATION = 1.15;
type Stat = {
    id: string;
    title: string;
    description: string;
    value: number;
    tone: string;
    icon: ReactNode;
};

function segmentFill(value: number, i: number): number {
    return Math.min(1, Math.max(0, (value * SEGMENTS) / 100 - i));
}
function StatCard({ stat }: {
    stat: Stat;
}) {
    const ref = useRef<HTMLElement>(null);
    const inView = useInView(ref, { once: true, amount: 0.4 });
    const reduce = useReducedMotion();
    const [hydrated, setHydrated] = useState(false);
    useEffect(() => setHydrated(true), []);
    const instant = hydrated && reduce === true;
    const shown = inView || instant;
    const motionKey = instant ? "instant" : "animated";
    const value = shown ? stat.value : 0;
    const valueTransition = reduce ? { duration: 0 } : { duration: VALUE_DURATION, ease: ARTEMIS_EASE_OUT };
    return (<article ref={ref} aria-labelledby={stat.id} className="art:flex art:min-w-0 art:flex-col art:rounded-3xl art:border art:border-border art:bg-background art:p-6 art:@min-[640px]/artemis:p-7">
      <div className="art:flex art:flex-col art:items-start art:gap-4">
        <span className="art:grid art:size-10 art:shrink-0 art:place-items-center art:rounded-full art:bg-muted art:text-foreground">{stat.icon}</span>
        <h3 id={stat.id} className="art:text-xl art:font-medium art:tracking-tight">
          {stat.title}
        </h3>
      </div>
      <p className="art:mt-2 art:text-sm art:leading-6 art:text-muted-foreground">{stat.description}</p>
      <div className="art:mt-10 art:@min-[640px]/artemis:mt-14">
        <p className="art:mb-6 art:flex art:text-5xl art:font-medium art:leading-none art:tracking-tight art:tabular-nums art:@min-[640px]/artemis:text-6xl">
          <NumberTicker key={motionKey} text={`${value}%`} duration={reduce ? 0 : VALUE_DURATION}/>
        </p>
        <div aria-hidden="true" className="art:mb-4 art:flex art:justify-between art:text-xs art:tabular-nums art:text-muted-foreground">
          <span>{"0%"}</span>
          <span>{"100%"}</span>
        </div>
        <div aria-hidden="true" className="art:relative">
          <div className="art:flex art:h-12 art:gap-0.5 art:@min-[640px]/artemis:h-14">
            {Array.from({ length: SEGMENTS }, (_, i) => {
            const fill = segmentFill(stat.value, i);
            const inset = shown ? Math.round((1 - fill) * 1000) / 10 : 0;
            return (<span key={i} className="art:relative art:h-full art:min-w-0 art:flex-1 art:overflow-hidden art:rounded-full art:bg-muted">
                  <motion.span key={motionKey} className={`art:absolute art:inset-0 art:origin-bottom art:rounded-full art:bg-current ${stat.tone}`} style={{ clipPath: `inset(0 ${inset}% 0 0)` }} initial={instant ? false : { opacity: 0, scaleY: 0.6 }} animate={shown ? { opacity: fill > 0 ? 1 : 0, scaleY: 1 } : { opacity: 0, scaleY: 0.6 }} transition={reduce ? { duration: 0 } : { duration: SEGMENT_DURATION, ease: ARTEMIS_EASE_OUT, delay: i * SEGMENT_STAGGER }}/>
                </span>);
        })}
          </div>
          <motion.div key={motionKey} className="art:pointer-events-none art:absolute art:left-0 art:w-0 art:-top-3" initial={instant ? false : { opacity: 0, left: "0%" }} animate={shown ? { opacity: 1, left: `${stat.value}%` } : { opacity: 0, left: "0%" }} transition={valueTransition}>
            <svg aria-hidden="true" viewBox="0 0 10 6" className={`art:h-1.5 art:w-2.5 art:-translate-x-1/2 art:fill-current ${stat.tone}`}>
              <path d="M0 0h10L5 6Z"/>
            </svg>
          </motion.div>
        </div>
      </div>
    </article>);
}
export default function StatsSegmentedProgress() {
