        value: 92,
        tone: "art:text-violet-300 art:dark:text-violet-300",
        icon: (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-check-check art:size-4" aria-hidden="true">
        <path d="M18 6 7 17l-5-5"/>
        <path d="m22 10-7.5 7.5L13 16"/>
      </svg>),
    },
    {
        id: `${artemisInstanceId}-R_apbsnpfdb_`,
        title: "Response time",
