          <header className="art:mx-auto art:mb-10 art:max-w-2xl art:text-center art:@min-[640px]/artemis:mb-14">
            <h2 id={`${artemisInstanceId}-R_9bsnpfdb_`} className="art:text-balance art:text-4xl art:font-medium art:tracking-tight">
              {"Less busywork. More progress."}
            </h2>
            <p className="art:mt-4 art:text-pretty art:text-sm art:leading-6 art:text-muted-foreground art:@min-[640px]/artemis:text-base">
